import { FC } from 'react';

interface ActionSheetAction {
    /** 选项文字 */
    text: string;
    /** 选项值 */
    value?: string | number;
    /** 是否为危险操作 */
    danger?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 自定义颜色 */
    color?: string;
    /** 描述文字 */
    description?: string;
}
interface ActionSheetProps {
    /** 是否打开 */
    open: boolean;
    /** 操作选项 */
    actions: ActionSheetAction[];
    /** 标题 */
    title?: string;
    /** 描述 */
    description?: string;
    /** 取消按钮文字，传空则不显示 */
    cancelText?: string;
    /** 点击选项回调 */
    onAction?: (action: ActionSheetAction, index: number) => void;
    /** 点击取消回调 */
    onCancel?: () => void;
    /** 关闭回调 */
    onClose?: () => void;
    /** 点击遮罩是否关闭 */
    closeOnOverlayClick?: boolean;
}

declare const ActionSheet: FC<ActionSheetProps>;

export { ActionSheet, ActionSheet as default };
export type { ActionSheetAction, ActionSheetProps };
